"""Finite, independently checkable advanced series constructions.

These are review candidates, never self-admitted content. The separate verifier
checks intermediate identities; analytic estimates remain explicit arguments.
"""
from __future__ import annotations
import itertools,json,math
from pathlib import Path
import sympy as s
from common import tex as L,prose as T,eq,truth,package,numeric_options
R=s.Rational
x,z=s.symbols('x z',real=True)
FAMILIES={}
def register(slug,group,method,why,prerequisites=()):
 def dec(fn):
  fid='quality-series-olympiad-'+slug
  FAMILIES[fid]={'familyId':fid,'topic':'series','difficulty':'olympiad','finiteInstanceIndices':list(range(8)),'relatedIdeaGroupId':group,'primaryTechnique':method,'difficultyRationale':why,'prerequisites':list(prerequisites),'sourceRecordIds':[],'fn':fn}
  return fn
 return dec
def numeric(fid,i,Q,A,W,steps,checks,analytic,parameters):
 meta={k:v for k,v in FAMILIES[fid].items() if k!='fn'}
 opts,code=numeric_options(A,W,i,fid)
 return package(meta,i,Q,opts,code,steps+[L(A)],checks,analytic,parameters=parameters)
def categorical(fid,i,Q,code,opts,steps,checks,analytic,parameters):
 meta={k:v for k,v in FAMILIES[fid].items() if k!='fn'}
 answer=next(o[1] for o in opts if o[0]==code)
 return package(meta,i,Q,opts,code,steps+[answer],checks,analytic,parameters=parameters)
def catalog():return [{k:v for k,v in f.items() if k!='fn'} for f in FAMILIES.values()]
def build(fid,index):
 if fid not in FAMILIES or type(index)is not int or index not in FAMILIES[fid]['finiteInstanceIndices']:raise ValueError('unknown finite advanced instance')
 return FAMILIES[fid]['fn'](fid,index)

@register('singular-cauchy-coefficient','singular-convolution-Riemann-limit','truncate-endpoint-singularities','An ordinary Riemann-sum argument fails at two singular endpoints; endpoint bounds are needed before evaluating the beta integral.',('improper integrals','Riemann sums','Gamma function'))
def singular_convolution(fid,i):
 p=[R(1,6),R(1,4),R(1,3),R(2,5),R(3,5),R(2,3),R(3,4),R(5,6)][i]
 A=s.gamma(1-p)**2/s.gamma(2-2*p)
 Q=T('Find the limit. The Gamma function is defined by the displayed integral.')+r'\quad\lim_{N\to\infty}N^{'+L(2*p-1)+r'}\sum_{k=1}^{N-1}\frac1{k^{'+L(p)+r'}(N-k)^{'+L(p)+r'}},\quad\Gamma(a)=\int_0^\infty t^{a-1}e^{-t}\,\mathrm{d}t\ (a>0).'
 W=[(s.gamma(1+p)**2/s.gamma(2+2*p),'reverse the signs of both singular exponents'),(s.gamma(1-p)**2/s.gamma(1-2*p),'omit the final beta denominator shift'),(2*A,'count both symmetric halves twice'),(A/2,'retain only one symmetric half'),(s.gamma(1-p)**2/s.gamma(3-2*p),'integrate one extra power in the beta denominator')]
 # Gamma(1-2p) may be negative; this is an authored index error, not a random offset.
 steps=[T('Write the normalized sum as a Riemann sum for an integrable function with two singular endpoints.'),r'f(t)=t^{-'+L(p)+r'}(1-t)^{-'+L(p)+r'},\qquad \frac1N\sum_{k=1}^{N-1}f(k/N).',T('On every closed subinterval strictly inside the unit interval, ordinary Riemann convergence applies. For a fixed endpoint cutoff delta below one half, the omitted left tail is bounded uniformly in N as follows; symmetry gives the same right-tail bound.'),r'\frac1N\sum_{1\le k\le\delta N}f(k/N)\le2^{'+L(p)+r'}N^{'+L(p-1)+r'}\sum_{1\le k\le\delta N}k^{-'+L(p)+r'}\le \frac{2^{'+L(p)+r'}}{'+L(1-p)+r'}\delta^{'+L(1-p)+r'}.',T('First let N tend to infinity with delta fixed, then let delta decrease to zero. The integral has the same vanishing endpoint bounds.'),r'\lim_{N\to\infty}\frac1N\sum_{k=1}^{N-1}f(k/N)=\int_0^1t^{-'+L(p)+r'}(1-t)^{-'+L(p)+r'}\,\mathrm{d}t=\frac{\Gamma('+L(1-p)+r')^2}{\Gamma('+L(2-2*p)+r')}.',T('The beta evaluation follows by changing variables to total size and proportion in the product of two Gamma integrals; nonnegative integrands justify that change.')]
 checks=[truth('both endpoint exponents are integrable',0<p<1),eq('sum normalization',s.simplify((x*(1-x))**(-p)),x**(-p)*(1-x)**(-p))] if False else [truth('both endpoint exponents integrable',0<p<1),eq('comparison primitive derivative',s.diff(x**(1-p)/(1-p),x),x**(-p))]
 return numeric(fid,i,Q,A,W,steps,checks,['For decreasing t^-p, the sum through M is at most the integral from zero to M, because each right-endpoint rectangle lies below its preceding strip. This proves the displayed bound including the first lattice term. Gamma/Beta change of variables is valid for positive parameters.'],{'p':str(p)})

@register('uniform-log-sine-threshold','uniform-convergence-sine-coefficients','block-counterexample-and-Dirichlet-tail','Requires both a necessary uniform Cauchy block bound and a uniform tail estimate with a moving frequency split.',('uniform convergence','summation by parts'))
def uniform_sine(fid,i):
 pairs=[(R(-1,2),0),(0,R(1,2)),(1,-1),(R(1,2),2),(-2,-1),(R(-1,3),R(2,3)),(R(3,2),0),(R(1,4),R(3,4))]
 p,q=pairs[i];p=s.sympify(p);q=s.sympify(q);a='uniform' if p>0 else 'not uniform';b='uniform' if q>0 else 'not uniform';code=a+'|'+b
 opts=[(u+'|'+v,r'\left('+T(u)+r',\ '+T(v)+r'\right)','correct' if u+'|'+v==code else 'Use pointwise convergence or absolute convergence in place of the uniform Cauchy criterion') for u,v in itertools.product(['uniform','not uniform'],repeat=2)]
 Q=r'S_p(x)=\sum_{n=2}^\infty\frac{\sin(nx)}{n(\ln n)^p},\qquad x\in\mathbb R.'+T('Choose the ordered uniform-convergence classification for the two displayed exponents on the whole real line.')+r'\quad p='+L(p)+r',\quad p='+L(q)+r'.'
 steps=[T('For a real exponent p, the sharp criterion is positive p. Periodicity and odd symmetry reduce the uniform estimate to x between zero and pi.'),T('To prove necessity, take x equal to one over N and sum from N through twice N. Every sine is bounded below by the positive minimum of sine on the interval from one to two.'),r'\sum_{n=N}^{2N}\frac{\sin(n/N)}{n(\ln n)^p}\ge c_p(\ln N)^{-p}\quad(N\ge2),\qquad c_p>0.',T('If p is nonpositive these blocks do not tend uniformly to zero, violating the uniform Cauchy criterion.'),T('For positive p, split any tail where n is about one over x. Before that split, bound sine by n times x; afterward use summation by parts and the geometric bound on partial sine sums.'),r'\left|\sum_{n=N}^{M}\frac{\sin(nx)}{n(\ln n)^p}\right|\le\frac{C_p}{(\ln N)^p}\quad(M\ge N\ge2),',T('Here ')+r'C_p'+T(' is a positive constant depending only on p. The first segment is bounded by x times its number of terms divided by the logarithmic factor. The second is bounded by a constant times its first coefficient divided by x; its starting index times x is bounded below. The bound tends to zero independently of x, proving sufficiency.'),r'p='+L(p)+T(': '+a+r'.')+r'\qquad p='+L(q)+T(': '+b+r'.')]
 checks=[truth('classification uses strict positive threshold',(p>0)==(a=='uniform')),truth('second classification uses strict positive threshold',(q>0)==(b=='uniform')),truth('sine block interval stays in positive half-period',2<s.pi)]
 return categorical(fid,i,Q,code,opts,steps,checks,['For fixed p the coefficient sequence is eventually positive decreasing even when p is nonpositive, so every pointwise series exists by Dirichlet (and vanishes at multiples of 2pi). Necessity uses a nonvanishing Cauchy block. Sufficiency uses 0<x<=pi and |sum sin(nx)|<=1/sin(x/2)<=pi/x. At x=0 the tail is zero. If N exceeds the moving split, apply only the Dirichlet part.'],{'p':str(p),'q':str(q)})

@register('lacunary-Abel-growth','lacunary-Abel-counting','logarithmic-cutoff-and-uniform-tail','The dominant term count grows logarithmically, while both errors require bounds uniform in the moving cutoff.',('infinite series','asymptotic estimates'))
def lacunary(fid,i):
 b=s.Integer(i+2);A=1/s.log(b)
 Q=r'\lim_{r\uparrow1}\frac{\displaystyle\sum_{k=0}^\infty r^{'+L(b)+r'^k}}{\ln\!\left(1/(1-r)\right)}=?'
 W=[(s.log(b),'replace the logarithmic change-of-base factor by its reciprocal'),(b/s.log(b),'count b terms for each occupied scale'),(1/(b*s.log(b)),'divide once more by the scale ratio'),(1/s.log(b+1),'count scales with the next integer base'),(1/s.log(b*b),'skip every second logarithmic scale')]
 steps=[r't=-\ln r>0,\qquad K=\left\lfloor\frac{\ln(1/t)}{\ln '+L(b)+r'}\right\rfloor.',T('For t small, there are K plus one terms at or before the transition scale. Their total deficit from one is bounded using the elementary exponential inequality.'),r'0\le\sum_{k=0}^{K}(1-e^{-t'+L(b)+r'^k})\le t\frac{'+L(b)+r'^{K+1}-1}{'+L(b-1)+r'}\le\frac{'+L(b)+r'}{'+L(b-1)+r'}.',T('After the transition, the remaining tail is bounded by a convergent series independent of t.'),r'0\le\sum_{k=K+1}^{\infty}e^{-t'+L(b)+r'^k}\le\sum_{j=0}^\infty e^{-'+L(b)+r'^j}<\infty.',r'\sum_{k=0}^\infty e^{-t'+L(b)+r'^k}=\frac{\ln(1/t)}{\ln '+L(b)+r'}+O(1)\quad(t\downarrow0).',T('Finally, minus the logarithm of r is asymptotic to one minus r, so the two logarithmic denominators have ratio one.'),r'\lim_{r\uparrow1}\frac{\sum_{k=0}^{\infty}r^{'+L(b)+r'^k}}{\ln(1/(1-r))}=\frac1{\ln '+L(b)+r'}.']
 checks=[eq('finite geometric deficit bound',sum(b**j for j in range(6)),(b**6-1)/(b-1)),truth('base is strictly greater than one',b>1),eq('change of variables near endpoint',s.limit(-s.log(1-x)/x,x,0),1)]
 return numeric(fid,i,Q,A,W,steps,checks,['The floor defining K implies b^K<=1/t<b^(K+1), hence t b^(K+1+j)>b^j. The uniform tail sum converges because b^j>=j+1 for b>=2. Big-O is with t decreasing to zero and b fixed.'],{'base':int(b)})

@register('quadratic-small-divisor','quadratic-irrational-small-divisor','integer-recurrence-and-conjugate-root','The small sine is controlled by an exact integer approximation from a recurrence, not by treating its argument as a generic oscillation.',('second-order recurrences','small-angle limit'))
def small_divisor(fid,i):
 m=s.Integer(i+3);D=m*m+4;a=(m+s.sqrt(D))/2;beta=(m-s.sqrt(D))/2;A=s.pi**2/D
 Q=r'q_0=0,\quad q_1=1,\quad q_{n+1}='+L(m)+r'q_n+q_{n-1}\ (n\ge1),\qquad\alpha=\frac{'+L(m)+r'+\sqrt{'+L(D)+r'}}2.\quad\lim_{n\to\infty}q_n^2\sin^2(\pi\alpha q_n)=?'
 W=[(s.pi**2/m**2,'replace the root separation by the recurrence coefficient'),(s.pi**2/(D*D),'square the squared root separation again'),(s.pi**2/(4*D),'introduce an extra half from the sine argument'),(4*s.pi**2/D,'lose the factor two in the quadratic roots'),(s.pi**2*m*m/D,'retain a spurious recurrence-coefficient factor')]
 steps=[r'\beta=\frac{'+L(m)+r'-\sqrt{'+L(D)+r'}}2,\qquad\alpha\beta=-1,\qquad |\beta|<1.',T('The recurrence and initial values give an exact closed form. Subtracting the next integer term exposes the exponentially small error.'),r'q_n=\frac{\alpha^n-\beta^n}{\alpha-\beta},\qquad\alpha q_n-q_{n+1}=-\beta^n.',T('Since the next recurrence value is an integer, adding its multiple of pi does not change the squared sine.'),r'\sin^2(\pi\alpha q_n)=\sin^2(\pi\beta^n),\qquad q_n^2\beta^{2n}=\frac{\big((-1)^n-\beta^{2n}\big)^2}{'+L(D)+r'}\longrightarrow\frac1{'+L(D)+r'}.',r'\frac{\sin(\pi\beta^n)}{\beta^n}\longrightarrow\pi,\qquad q_n^2\sin^2(\pi\alpha q_n)\longrightarrow\frac{\pi^2}{'+L(D)+r'}.']
 checks=[eq('quadratic conjugate product',a*beta,-1),eq('root separation squared',(a-beta)**2,D)]
 q=[s.Integer(0),s.Integer(1)]
 for n in range(1,8):q.append(m*q[-1]+q[-2])
 checks += [eq('integer approximation identity n='+str(n),a*q[n]-q[n+1],-beta**n) for n in range(1,8)]
 return numeric(fid,i,Q,A,W,steps,checks,['The characteristic roots are distinct and solve the recurrence; checking the two initial values proves the closed form for all n by induction. Because alpha>1 and alpha beta=-1, the conjugate has magnitude below one. Squaring removes the alternating sign of its product with alpha.'],{'coefficient':int(m)})

@register('alternating-infinite-product','conditional-product-second-order-drift','logarithmic-expansion-with-summable-remainder','An alternating first-order logarithmic term converges while the even second-order drift determines whether the product collapses.',('alternating series','infinite products','Taylor remainder'))
def alternating_product(fid,i):
 pairs=[(R(1,4),R(1,2)),(R(1,2),R(3,4)),(1,R(1,3)),(R(2,3),R(5,4)),(R(1,5),R(2,5)),(R(2,5),R(3,5)),(R(4,5),R(1,2)),(R(3,2),R(5,6))]
 p,q=pairs[i];a='positive' if p>R(1,2) else 'zero';b='positive' if q>R(1,2) else 'zero';code=a+'|'+b
 opts=[(u+'|'+v,r'\left('+T(u)+r',\ '+T(v)+r'\right)','correct' if u+'|'+v==code else 'Ignore the second-order logarithmic drift or impose absolute convergence of the first-order term') for u,v in itertools.product(['positive','zero'],repeat=2)]
 Q=r'P_p=\lim_{N\to\infty}\prod_{n=2}^{N}\left(1+\frac{(-1)^n}{n^p}\right),\qquad p>0.'+T('Classify the two limits as strictly positive or zero, in the displayed order.')+r'\quad p='+L(p)+r',\quad p='+L(q)+r'.'
 steps=[T('Every factor is positive. Pair an even index with the following odd index and write u and v for their positive magnitudes.'),r'u=(2k)^{-p},\quad v=(2k+1)^{-p},\qquad (1+u)(1-v)=1+(u-v)-uv.',T('The sum of u minus v converges by the alternating test. For large k, the negative product term has size proportional to k to the power minus twice p and dominates u minus v whenever twice p is at most one.'),r'0<u-v\le p(2k)^{-p-1},\qquad uv\sim(2k)^{-2p}.',T('If p is at most one half, each paired logarithm is eventually negative and asymptotic to minus uv. Their sum diverges to minus infinity, and the product tends to zero.'),T('If p exceeds one half, expand each logarithm to first order. The remainders are absolutely summable because they are bounded by a constant times n to the power minus twice p.'),r'\ln(1+(-1)^nn^{-p})=(-1)^nn^{-p}+O(n^{-2p}).',T('The logarithm sum then has a finite real limit, giving a strictly positive product. An unpaired final factor tends to one and does not change either conclusion.'),r'p='+L(p)+T(': '+a+r'.')+r'\qquad p='+L(q)+T(': '+b+r'.')]
 checks=[eq('paired product identity',(1+x)*(1-z),1+(x-z)-x*z),truth('first classification uses threshold one half',(p>R(1,2))==(a=='positive')),truth('second classification uses threshold one half',(q>R(1,2))==(b=='positive'))]
 return categorical(fid,i,Q,code,opts,steps,checks,['For 0<p<=1/2, (u-v)/(uv)=O(k^(p-1)) tends to zero. The paired increment is asymptotic to -uv and tends to zero, so log(1+increment) has the same asymptotic. The divergent positive p-series sum uv proves logarithmic collapse including the boundary. For p>1/2 the absolute quadratic remainder converges; no unjustified cubic summability is assumed.'],{'p':str(p),'q':str(q)})

@register('Dirichlet-moment-uniqueness','Dirichlet-series-coefficient-recovery','smallest-index-dominance','Recovers all coefficients from integer samples of a Dirichlet series by isolating the first possible discrepancy and controlling its infinite tail.',('dominated convergence','absolutely convergent series'))
def moment_unique(fid,i):
 m=i+2;A=s.Integer(m*m-1)
 Q=T('A real sequence is absolutely summable and satisfies the displayed identities for every positive integer k. Find its specified coefficient.')+r'\quad\sum_{n=1}^{\infty}|a_n|<\infty,\quad\sum_{n=1}^{\infty}\frac{a_n}{n^k}=\sum_{n=1}^{\infty}\frac{n^2-1}{'+str(m+2)+r'^n n^k}\ (k=1,2,\ldots).\quad '+str(m+2)+r'^{'+str(m)+r'}a_{'+str(m)+r'}=?'
 W=[(s.Integer(m*m),'ignore the subtracted constant in the recovered coefficient'),(s.Integer(m*m-1)/(m+2)**m,'return the coefficient before the requested rescaling'),(s.Integer(m-1),'replace the quadratic coefficient by a first difference'),(s.Integer((m+1)**2-1),'shift the recovered index forward'),(s.Integer((m-1)**2-1),'shift the recovered index backward'),(s.Integer(m*m-1)*(m+2),'include one extra power in the rescaling')]
 steps=[r'b_n=a_n-\frac{n^2-1}{'+str(m+2)+r'^n},\qquad\sum_{n=1}^{\infty}|b_n|<\infty,\qquad\sum_{n=1}^{\infty}\frac{b_n}{n^k}=0.',T('Suppose a coefficient is nonzero, and let j be its smallest index. Multiply the identity by j to the power k.'),r'0=b_j+\sum_{n>j}b_n\left(\frac jn\right)^k.',T('For each index greater than j the ratio power tends to zero, and each term is bounded in magnitude by the summable sequence of absolute coefficients. Dominated convergence forces the tail to zero, contradicting the choice of j.'),r'b_n=0\quad(n\ge1),\qquad a_'+str(m)+r'=\frac{'+str(m*m-1)+r'}{'+str(m+2)+r'^{'+str(m)+r'}},\qquad '+str(m+2)+r'^{'+str(m)+r'}a_'+str(m)+r'='+str(m*m-1)+r'.']
 checks=[eq('requested recovered and rescaled coefficient',s.Rational(m*m-1,(m+2)**m)*(m+2)**m,A),truth('geometric coefficient sequence absolutely summable',m+2>1)]
 return numeric(fid,i,Q,A,W,steps,checks,['The comparison sequence (n^2-1)/(m+2)^n is absolutely summable by the ratio test. The difference is therefore in l1. The well-ordering of positive integers supplies a smallest nonzero index. Dominated convergence is applied to counting measure with the displayed l1 bound, not an unjustified interchange for merely conditional coefficients.'],{'index':m,'geometricBase':m+2})

@register('least-energy-sequence','Hilbert-sequence-two-moment-projection','Gram-projection-and-orthogonal-remainder','Two infinite linear constraints determine a two-dimensional minimum-energy projection; the residual norm proves a global attainable optimum.',('Cauchy-Schwarz','geometric moments'))
def least_energy(fid,i):
 m=s.Integer(i+2);r=1/m;u=m-1;v=m+1
 G=s.Matrix([[r*r/(1-r*r),r*r/(1-r*r)**2],[r*r/(1-r*r)**2,r*r*(1+r*r)/(1-r*r)**3]])
 c=s.Matrix([u,v]);coeff=G.inv()*c;A=(c.T*coeff)[0]
 diag=u*u/G[0,0]+v*v/G[1,1]
 W=[(diag,'minimize the two constraints independently despite nonorthogonal coefficient sequences'),((u*u+v*v)/(G[0,0]+G[1,1]),'replace the Gram matrix by its trace'),(A/2,'include a spurious half in the squared norm'),(2*A,'count the real energy twice'),((s.Matrix([u,-v]).T*G.inv()*s.Matrix([u,-v]))[0],'reverse the second moment sign'),((c.T*G*c)[0],'multiply by the Gram matrix instead of its inverse')]
 Q=T('Among all real sequences satisfying the displayed finite-energy and moment conditions, find the minimum energy.')+r'\quad\sum_{n=1}^{\infty}a_n^2<\infty,\quad\sum_{n=1}^{\infty}\frac{a_n}{'+L(m)+r'^n}='+L(u)+r',\quad\sum_{n=1}^{\infty}\frac{na_n}{'+L(m)+r'^n}='+L(v)+r'.\qquad\min\sum_{n=1}^{\infty}a_n^2=?'
 steps=[T('Let the two constraint vectors have entries r to the power n and n times r to the power n, with the indicated value of r. Their Gram matrix records all pairwise inner products.'),r'r='+L(r)+r',\qquad G=\begin{pmatrix}\sum_{n\ge1}r^{2n}&\sum_{n\ge1}nr^{2n}\\\sum_{n\ge1}nr^{2n}&\sum_{n\ge1}n^2r^{2n}\end{pmatrix}='+L(G)+r'.',T('Differentiate the geometric series to obtain these entries. The two vectors are linearly independent, so the Gram matrix is positive definite.'),r'\binom{\lambda}{\mu}=G^{-1}\binom{'+L(u)+r'}{'+L(v)+r'}='+L(coeff)+r',\qquad a_n^*=(\lambda+\mu n)r^n.',T('This sequence meets both constraints. Any other admissible sequence differs from it by a vector orthogonal to each constraint vector and hence orthogonal to the minimizing sequence.'),r'a_n=a_n^*+h_n\quad\Longrightarrow\quad\sum_{n\ge1}a_n^2=\sum_{n\ge1}(a_n^*)^2+\sum_{n\ge1}h_n^2\ge\sum_{n\ge1}(a_n^*)^2.',r'\sum_{n\ge1}(a_n^*)^2=\begin{pmatrix}'+L(u)+r'&'+L(v)+r'\end{pmatrix}G^{-1}\binom{'+L(u)+r'}{'+L(v)+r'}='+L(A)+r'.']
 checks=[eq('constructed minimizer satisfies both linear constraints',G*coeff,c),eq('minimizer energy equals quadratic-form answer',(coeff.T*G*coeff)[0],A),truth('Gram determinant positive',G.det()>0)]
 return numeric(fid,i,Q,A,W,steps,checks,['All moment series converge by Cauchy-Schwarz because the two coefficient sequences lie in l2. Their independence follows because n is not constant. The candidate has finite energy due to geometric decay. The Pythagorean identity proves both global minimality and attainment, with no finite truncation substituted for the infinite problem.'],{'base':int(m),'firstMoment':int(u),'secondMoment':int(v)})

@register('Legendre-recurrence-generating','three-term-recurrence-generating-ODE','sum-recurrence-and-initial-value','A polynomial recurrence must be converted to a differential equation for its generating function, with a branch fixed by the initial coefficient.',('power series','first-order differential equations'))
def legendre_generating(fid,i):
 m=s.Integer(i+3);a=R(m-1,m+1);r=1/m;A=1/s.sqrt(1-2*a*r+r*r)
 W=[(1/(1-2*a*r+r*r),'omit the half exponent after integrating the differential equation'),(1/s.sqrt(1+2*a*r+r*r),'reverse the recurrence middle sign'),(1/s.sqrt(1-2*a*r-r*r),'reverse the last recurrence sign'),(s.sqrt(1-2*a*r+r*r),'reverse the logarithmic integration sign'),(1/s.sqrt(1-a*r+r*r),'lose the doubled middle coefficient'),(1/s.sqrt(1-2*a*r+2*r*r),'count the index-shift square term twice')]
 Q=r'P_0=1,\quad P_1='+L(a)+r',\quad(n+1)P_{n+1}=(2n+1)'+L(a)+r'P_n-nP_{n-1}\quad(n\ge1).\qquad\sum_{n=0}^{\infty}\frac{P_n}{'+L(m)+r'^n}=?'
 steps=[r'F(z)=\sum_{n=0}^{\infty}P_nz^n,\qquad F(0)=1.',T('Multiply the recurrence by z to the power n and sum. Including the initial relation at n zero makes all index shifts exact.'),r'(1-2'+L(a)+r'z+z^2)F\prime(z)=('+L(a)+r'-z)F(z).',T('Integrating the logarithmic derivative and using the initial coefficient gives the generating function with the positive square root at zero.'),r'F(z)=(1-2'+L(a)+r'z+z^2)^{-1/2}.',T('The two complex zeros of the quadratic have modulus one because the fixed middle parameter lies strictly between minus one and one. Thus this branch is analytic in the open unit disk; its coefficient recurrence proves that its Taylor coefficients are precisely the given sequence.'),r'F\left('+L(r)+r'\right)=\frac1{\sqrt{1-2\left('+L(a)+r'\right)\left('+L(r)+r'\right)+\left('+L(r)+r'\right)^2}}='+L(A)+r'.']
 F=(1-2*a*x+x*x)**(-R(1,2));checks=[eq('differential equation for generated function',(1-2*a*x+x*x)*s.diff(F,x),(a-x)*F),eq('initial coefficient',F.subs(x,0),1),truth('evaluation strictly inside analytic disk',0<r<1 and -1<a<1)]
 return numeric(fid,i,Q,A,W,steps,checks,['One may derive the recurrence formally first; the explicit analytic branch then establishes convergence rather than assuming it. The branch has value one at zero and no zero of its denominator in |z|<1. Real evaluation at r>0 uses the positive root.'],{'coefficient':str(a),'base':int(m)})

@register('rooted-tree-weighted-series','rooted-tree-Lagrange-branch','Lagrange-inversion-and-branch-continuation','The implicit generating function has multiple real branches; analytic continuation from zero and a differentiated identity select the correct weighted sum.',('Lagrange inversion','implicit functions','power-series radius'))
def rooted_tree(fid,i):
 a=R(i+1,i+3);r=a*s.exp(-a);A=a/(1-a)**3
 W=[(a/(1-a),'omit the second index weighting'),(a/(1-a)**2,'differentiate the numerator but not the implicit denominator'),(a/(1+a)**3,'reverse the sign in the implicit derivative'),(a/(1-a)**4,'include an extra implicit derivative denominator'),((1+a)/(1-a)**3,'include an unwanted zero-index contribution'),(2*a/(1-a)**3,'double the rooted-tree coefficient')]
 Q=r'\sum_{n=1}^{\infty}\frac{n^{n+1}}{n!}\left('+L(a)+r'e^{-'+L(a)+r'}\right)^n=?'
 steps=[T('Let T be the power-series solution at zero of the following implicit equation. Lagrange inversion identifies its coefficients.'),r'T(z)=ze^{T(z)},\quad T(0)=0,\qquad [z^n]T(z)=\frac1n[u^{n-1}]e^{nu}=\frac{n^{n-1}}{n!}.',T('Stirling asymptotics give radius one over e, and the selected argument is strictly inside it. On the real branch beginning at zero, T stays below one; the map from T to T times its negative exponential is strictly increasing there.'),r'T\!\left('+L(a)+r'e^{-'+L(a)+r'}\right)='+L(a)+r'.',T('The requested extra square index weight comes from applying the Euler derivative twice.'),r'zT\prime(z)=\frac{T}{1-T},\qquad\left(z\frac{\mathrm{d}}{\mathrm{d}z}\right)^2T(z)=\frac{T}{(1-T)^3}.',r'\sum_{n=1}^{\infty}\frac{n^{n+1}}{n!}\left('+L(a)+r'e^{-'+L(a)+r'}\right)^n=\frac{'+L(a)+r'}{(1-'+L(a)+r')^3}='+L(A)+r'.']
 checks=[eq('Euler derivative of first weight',s.diff(x/(1-x),x)*x/(1-x),x/(1-x)**3),truth('chosen tree value lies on small branch',0<a<1),eq('argument is implicit image',r,a*s.exp(-a))]
 return numeric(fid,i,Q,A,W,steps,checks,['Lagrange inversion is used for the analytic solution with T(0)=0. Stirling gives nth-root coefficient limit e, hence radius 1/e. Since a is strictly between zero and one, a exp(-a)<1/e and branch uniqueness follows from positivity of derivative exp(-T)(1-T). Twice differentiating the power series is valid strictly inside that radius.'],{'treeValue':str(a)})

@register('finite-cycle-resolvent','cycle-resolvent-Chebyshev-trace','roots-logarithmic-derivative','A trigonometric reciprocal sum is converted to a logarithmic derivative of a polynomial whose zeros have the required multiplicities.',('Chebyshev polynomials','logarithmic differentiation'))
def cycle_resolvent(fid,i):
 n=[13,17,19,23,29,31,37,41][i];a=R(3,2);P=s.chebyshevt(n,x)-1;A=s.factor(s.diff(P,x).subs(x,a)/P.subs(x,a))
 W=[(s.factor(P.subs(x,a)/s.diff(P,x).subs(x,a)),'invert the logarithmic derivative'),(A/n,'average the resolvents instead of summing'),(n*A,'count every vertex multiplicity a second time'),(s.factor(s.diff(s.chebyshevt(n,x)+1,x).subs(x,a)/(s.chebyshevt(n,a)+1)),'use the antiperiodic root set'),(s.factor(s.diff(s.chebyshevu(n-1,x),x).subs(x,a)/s.chebyshevu(n-1,a)),'use only the interior sine roots')]
 Q=r'\sum_{k=0}^{'+str(n-1)+r'}\frac1{\frac32-\cos(2\pi k/'+str(n)+r')}=?'
 steps=[T('Define the Chebyshev polynomials by the recurrence. Their trigonometric identity follows by induction from the cosine addition formula.'),r'T_0(z)=1,\quad T_1(z)=z,\quad T_{j+1}(z)=2zT_j(z)-T_{j-1}(z),\qquad T_j(\cos\theta)=\cos(j\theta).',T('The polynomial minus one has exactly the roots in the sum. Interior cosine roots are double because the two angles give the same value; endpoint roots have their corresponding single multiplicities.'),r'T_'+str(n)+r'(z)-1=2^{'+str(n-1)+r'}\prod_{k=0}^{'+str(n-1)+r'}\left(z-\cos(2\pi k/'+str(n)+r')\right).',T('Logarithmically differentiate this finite product. The evaluation point exceeds every root, so no denominator vanishes.'),r'\sum_{k=0}^{'+str(n-1)+r'}\frac1{z-\cos(2\pi k/'+str(n)+r')}=\frac{T_'+str(n)+r'\prime(z)}{T_'+str(n)+r'(z)-1}.',r'\frac{T_'+str(n)+r'\prime(3/2)}{T_'+str(n)+r'(3/2)-1}='+L(A)+r'.']
 checks=[eq('Chebyshev recurrence',s.chebyshevt(n,x),2*x*s.chebyshevt(n-1,x)-s.chebyshevt(n-2,x)),truth('resolvent evaluation lies above spectrum',a>1),eq('root multiplicity degree',s.degree(P,x),n)]
 return numeric(fid,i,Q,A,W,steps,checks,['T_n(cos theta)-1 vanishes at all displayed angles. At interior paired angles its first theta derivative vanishes and second does not, giving double roots in z; at theta=0 and, when relevant, pi the root in z is single. These multiplicities total n, and the leading coefficient gives the product constant.'],{'cycleSize':n})

@register('weighted-subset-q-product','q-binomial-subset-generating','coefficient-recurrence-and-finite-product','The weighted subset sum is recognized through a two-way inclusion recurrence, yielding a finite product with a nontrivial normalization.',('finite products','polynomial coefficients'))
def q_subset(fid,i):
 n=i+12;k=5+i%3;q=s.Integer(2);A=s.prod((1-q**(n-j))/(1-q**(j+1)) for j in range(k))*q**(k*(k-1)//2)
 # Coefficient has a real combinatorial sum; all choices are related index/normalization mistakes.
 W=[(A/q**(k*(k-1)//2),'omit the minimal-index weight'),(A*q**k,'start the selectable indices at one rather than zero'),(A/q**k,'shift every selected index down by one'),(s.binomial(n,k)*q**(k*(k-1)//2),'replace varying subset weights by the minimum weight'),(s.prod((1-q**(n+1-j))/(1-q**(j+1)) for j in range(k))*q**(k*(k-1)//2),'allow one extra selectable index'),(s.prod((1-q**(n-j))/(1-q**(j+1)) for j in range(k-1))*q**((k-1)*(k-2)//2),'select one fewer index')]
 Q=r'\sum_{0\le j_1<\cdots<j_'+str(k)+r'\le '+str(n-1)+r'}2^{j_1+\cdots+j_'+str(k)+r'}=?'
 steps=[r'F_N(z)=\prod_{j=0}^{N-1}(1+2^jz)=\sum_{h=0}^{N}C_{N,h}z^h.',T('Selecting the z term from exactly h factors gives the weighted subsets. Splitting according to whether the largest index is selected gives the coefficient recurrence.'),r'C_{N,h}=C_{N-1,h}+2^{N-1}C_{N-1,h-1},\qquad C_{N,0}=1.',T('Induction in this recurrence gives the finite product formula; the normalization is the weight of the smallest possible set of h indices.'),r'C_{N,h}=2^{h(h-1)/2}\prod_{j=0}^{h-1}\frac{2^{N-j}-1}{2^{j+1}-1}.',r'C_{'+str(n)+','+str(k)+r'}=2^{'+str(k*(k-1)//2)+r'}\prod_{j=0}^{'+str(k-1)+r'}\frac{2^{'+str(n)+r'-j}-1}{2^{j+1}-1}='+L(A)+r'.']
 brute=sum(2**sum(J) for J in itertools.combinations(range(n),k));checks=[eq('direct weighted subset enumeration',brute,A),eq('independent finite product coefficient',s.Poly(s.prod(1+2**j*x for j in range(n)),x).nth(k),A)]
 return numeric(fid,i,Q,A,W,steps,checks,['The product formula is proved by induction using the coefficient recurrence; after factoring the common product, the two terms combine by (2^(N-h)-1)+2^(N-h)(2^h-1)=2^N-1. Empty products equal one, and out-of-range coefficients are zero. This is finite, so no convergence exchange is involved.'],{'size':n,'selected':k})

@register('Poisson-partition-moment','Poisson-moment-set-partitions','falling-factorial-basis-and-exponential-sum','A factorial-weighted power sum is evaluated through set partitions and falling-factorial moments rather than repeated differentiation of an exponential.',('set partitions','exponential series'))
def dobinski(fid,i):
 n=i+8;A=s.bell(n)
 W=[(s.bell(n-1),'use one fewer labeled position'),(s.bell(n+1),'include an extra labeled position'),(s.factorial(n),'count ordered arrangements instead of set partitions'),(2**(n-1),'count compositions rather than set partitions'),(s.bell(n)*n,'distinguish one block or element unnecessarily'),(s.bell(n)/n,'divide an unlabeled-block count by the number of positions')]
 Q=r'\frac1e\sum_{k=0}^{\infty}\frac{k^{'+str(n)+r'}}{k!}=?'
 steps=[T('Let S(n,j) count partitions of an n-element labeled set into j nonempty unlabeled blocks. Counting functions into a k-element set by their nonempty fibers gives the falling-factorial identity.'),r'k^n=\sum_{j=0}^{n}S(n,j)k^{\underline j},\qquad k^{\underline j}=k(k-1)\cdots(k-j+1),\quad k^{\underline0}=1.',T('Divide by k factorial and sum. The j sum is finite, and each falling-factorial moment reduces to the exponential series.'),r'e^{-1}\sum_{k=0}^{\infty}\frac{k^{\underline j}}{k!}=e^{-1}\sum_{k=j}^{\infty}\frac1{(k-j)!}=1.',T('The requested value is therefore the total number of set partitions. Compute it with the recurrence that either puts the last element into an existing block or makes a new singleton.'),r'S(n,j)=jS(n-1,j)+S(n-1,j-1),\quad S(0,0)=1,\quad S(n,0)=0\ (n>0).',r'e^{-1}\sum_{k=0}^{\infty}\frac{k^{'+str(n)+r'}}{k!}=\sum_{j=0}^{'+str(n)+r'}S('+str(n)+r',j)='+L(A)+r'.']
 from sympy.functions.combinatorial.numbers import stirling
 poly=sum(stirling(n,j,kind=2)*s.ff(x,j) for j in range(n+1));checks=[eq('falling factorial identity as polynomial',poly,x**n),eq('partition count',sum(stirling(n,j,kind=2) for j in range(n+1)),A)]
 return numeric(fid,i,Q,A,W,steps,checks,['The factorial-weighted polynomial series converges absolutely by the ratio test. For integer k<j the falling factorial vanishes. Counting maps by fibers proves the basis conversion independently of the final sum; finite j interchange requires no infinite Fubini claim.'],{'power':n})

@register('factorial-floor-reconstruction','factorial-floor-exact-remainder','integer-truncation-and-generating-function','A floor containing the transcendental number e is resolved by a strict factorial remainder bound before a justified double-sum transformation.',('exponential remainder','floor function','nonnegative sums'))
def factorial_floor(fid,i):
 b=s.Integer(i+3);r=1/b;A=s.exp(r)/(1-r)-1
 W=[(s.exp(r)/(1-r),'include the omitted zero-index term'),((s.exp(r)-1)/(1-r),'drop the constant Taylor contribution in every coefficient'),(s.exp(r)/(1+r)-1,'use an alternating geometric tail'),(s.exp(r)/(1-r)**2-1,'count each geometric tail with an extra linear weight'),(s.exp(r)*(1-r)-1,'multiply rather than divide by the geometric normalization'),(s.exp(r)/(1-r)-1-r,'omit the first included factorial-floor term')]
 Q=r'\sum_{n=1}^{\infty}\frac{\lfloor e\,n!\rfloor}{n!\,'+L(b)+r'^n}=?'
 steps=[T('Multiply the exponential series by n factorial. Its terms through index n are integers, while the positive remaining tail lies strictly between zero and one.'),r'e\,n!=\sum_{j=0}^{n}\frac{n!}{j!}+R_n,\qquad 0<R_n=\sum_{h=1}^{\infty}\frac1{(n+1)\cdots(n+h)}<1\quad(n\ge1).',T('For n at least two, the tail is bounded by the geometric sum one over n. For n equal to one, the same upper bound is strict because denominators after the first term exceed the geometric comparison.'),r'\frac{\lfloor e\,n!\rfloor}{n!}=\sum_{j=0}^{n}\frac1{j!}.',T('Insert the positive geometric weight and reverse the nonnegative double sum. Define its ratio r as follows.'),r'r='+L(r)+r',\qquad\sum_{n=0}^{\infty}r^n\sum_{j=0}^{n}\frac1{j!}=\sum_{j=0}^{\infty}\frac{r^j}{j!}\sum_{h=0}^{\infty}r^h=\frac{e^r}{1-r}.',T('The auxiliary zero-index coefficient is one; subtract it because the requested sum begins at one.'),r'\sum_{n=1}^{\infty}\frac{\lfloor e\,n!\rfloor}{n!\,'+L(b)+r'^n}=\frac{e^{'+L(r)+r'}}{1-'+L(r)+r'}-1='+L(A)+r'.']
 checks=[eq('first three floor coefficients from integer truncated sums',sum(s.factorial(3)/s.factorial(j) for j in range(4)),16),truth('geometric argument interior',0<r<1)]
 return numeric(fid,i,Q,A,W,steps,checks,['The remainder has denominator factors at least n+1 and at least one strict improvement beyond the first term; thus R_n<sum_(h>=1)(n+1)^-h=1/n<=1. All transformed summands are nonnegative, so Tonelli is justified before convergence is concluded by the finite closed form. The artificial n=0 truncated coefficient is one, not floor(e); no identity at n=0 is asserted.'],{'base':int(b)})

@register('Liouville-Dirichlet-product','multiplicative-Dirichlet-Euler-product','prime-factor-parity-and-absolute-Euler-product','Complete multiplicativity and unique factorization produce an Euler product whose local factors reveal a ratio of zeta values.',('unique factorization','Euler products'))
def liouville(fid,i):
 p=s.Integer(i+2);A=s.zeta(2*p)/s.zeta(p)
 W=[(s.zeta(p)/s.zeta(2*p),'invert each prime factor'),(1/s.zeta(p),'treat prime powers of exponent two as forbidden'),(s.zeta(2*p),'discard all nonsquare terms'),(1/s.zeta(2*p),'invert the square-only product'),((1-2**(1-p))*s.zeta(p),'replace prime-factor parity by integer parity'),(s.zeta(p),'ignore every multiplicative sign')]
 Q=T('Let ')+r'\Omega(n)'+T(' be the total number of prime factors of the positive integer ')+r'n'+T(' counted with multiplicity, with ')+r'\Omega(1)=0.'+T(' Define the zeta function by its convergent series.')+r'\quad\Omega(12)=3,\qquad\zeta(s)=\sum_{n=1}^{\infty}n^{-s}\ (s>1).\quad\sum_{n=1}^{\infty}\frac{(-1)^{\Omega(n)}}{n^{'+L(p)+r'}}=?'
 steps=[T('Adding prime-factor multiplicities makes the sign completely multiplicative. Absolute convergence follows by comparison with the displayed zeta series.'),r'(-1)^{\Omega(ab)}=(-1)^{\Omega(a)}(-1)^{\Omega(b)},\qquad\sum_{n\ge1}\frac{|(-1)^{\Omega(n)}|}{n^{'+L(p)+r'}}=\zeta('+L(p)+r')<\infty.',T('Unique factorization therefore permits a product over primes. For each prime ell, its local power series is geometric.'),r'\sum_{n=1}^{\infty}\frac{(-1)^{\Omega(n)}}{n^{'+L(p)+r'}}=\prod_{\ell\ {\rm prime}}\left(\sum_{j=0}^{\infty}(-\ell^{-'+L(p)+r'})^j\right)=\prod_{\ell\ {\rm prime}}\frac1{1+\ell^{-'+L(p)+r'}}.',r'\frac1{1+u}=\frac{1-u}{1-u^2}\quad\Longrightarrow\quad\prod_{\ell\ {\rm prime}}\frac{1-\ell^{-'+L(p)+r'}}{1-\ell^{-'+L(2*p)+r'}}=\frac{\zeta('+L(2*p)+r')}{\zeta('+L(p)+r')}.']
 checks=[eq('local Euler factor algebra',1/(1+x),(1-x)/(1-x*x)),truth('absolute Dirichlet convergence exponent',p>1)]
 return numeric(fid,i,Q,A,W,steps,checks,['Finite prime products sum precisely over integers supported on those primes. Absolute convergence lets the finite support restriction grow to all integers. The zeta Euler product follows by the same positive geometric expansion; dividing the two convergent products is legitimate because zeta(s)>0 for real s>1.'],{'exponent':int(p)})

@register('Riesz-product-energy','dissociated-Fourier-frequencies','balanced-digit-uniqueness-and-constant-term','The squared product contains many frequencies, but a largest-frequency argument excludes every nontrivial constant contribution.',('trigonometric orthogonality','finite Fourier series'))
def riesz(fid,i):
 b=i+5;N=i+4;a=R(i+1,i+2);A=(1+a*a/2)**N
 W=[((1+a*a)**N,'forget that the mean square of cosine is one half'),((1+a/2)**N,'fail to square the cosine amplitude'),((1+a*a/4)**N,'count only one of the paired exponential constant terms'),(1+N*a*a/2,'discard products of the independent constant contributions'),((1+2*a*a)**N,'double the two exponential frequencies twice'),((1+a*a/2)**(N+1),'include an extra frequency factor')]
 Q=r'\frac1{2\pi}\int_0^{2\pi}\prod_{j=0}^{'+str(N-1)+r'}\left(1+'+L(a)+r'\cos('+str(b)+r'^j x)\right)^2\,\mathrm{d}x=?'
 steps=[T('The average over a full period extracts the zero Fourier coefficient. In each squared factor, the only frequencies are zero, plus or minus the base frequency, and plus or minus twice that frequency.'),r'(1+a\cos\theta)^2=1+\frac{a^2}2+2a\cos\theta+\frac{a^2}2\cos(2\theta),\qquad a='+L(a)+r'.',T('A frequency sum can vanish only if every selected digit is zero. If J is its largest nonzero digit index, the largest term strictly exceeds all possible lower-frequency cancellation.'),r'\left|d_J'+str(b)+r'^J\right|\ge '+str(b)+r'^J>2\sum_{j=0}^{J-1}'+str(b)+r'^j,\qquad d_j\in\{-2,-1,0,1,2\}.',T('Consequently the zero coefficient of the product is exactly the product of the individual zero coefficients.'),r'\frac1{2\pi}\int_0^{2\pi}\prod_{j=0}^{'+str(N-1)+r'}\left(1+'+L(a)+r'\cos('+str(b)+r'^jx)\right)^2\,\mathrm{d}x=\left(1+\frac{('+L(a)+r')^2}2\right)^{'+str(N)+r'}='+L(A)+r'.']
 checks=[eq('single-factor trigonometric expansion',s.expand_trig((1+a*s.cos(x))**2)-(1+a*a/2+2*a*s.cos(x)+a*a*s.cos(2*x)/2),0),truth('largest-frequency dominance at smallest case',2/(R(b)-1)<1)]
 return numeric(fid,i,Q,A,W,steps,checks,['The average of exp(i k x) over a full period is zero for every nonzero integer k and one for k=0. The finite product expansion is valid without any infinite-sum exchange. The dominance bound uses b>=5; no assertion of independence of random variables is needed.'],{'base':b,'factors':N,'amplitude':str(a)})

@register('Euler-harmonic-weight-three','positive-double-series-two-countings','two-regroupings-and-diagonal-separation','A positive double sum admits two different exact reorganizations; equating them determines a harmonic-weighted series without assuming a memorized Euler sum.',('Tonelli theorem','telescoping'))
def harmonic_euler(fid,i):
 m=i+2;tail=sum(s.harmonic(j)/j**2 for j in range(1,m));A=2*s.zeta(3)-tail
 W=[(s.zeta(3)-tail,'omit the off-diagonal contribution'),(3*s.zeta(3)-tail,'count the diagonal twice'),(2*s.zeta(3)-tail-s.harmonic(m)/m**2,'omit the first included term'),(2*s.zeta(3)-tail+s.harmonic(m-1)/(m-1)**2,'retain the last excluded term'),((2*s.zeta(3)-tail)/2,'halve the entire sum after the two-counting identity'),(2*(2*s.zeta(3)-tail),'double both symmetric and diagonal contributions')]
 Q=r'H_n=\sum_{j=1}^{n}\frac1j,\qquad\zeta(3)=\sum_{n=1}^{\infty}\frac1{n^3}.\quad\sum_{n='+str(m)+r'}^{\infty}\frac{H_n}{n^2}=?'
 steps=[r'S=\sum_{n=1}^{\infty}\frac{H_n}{n^2},\qquad B=\sum_{u,v\ge1}\frac1{uv(u+v)}.',T('The harmonic bound by one plus the natural logarithm proves S is finite. All terms in the double sum are nonnegative, allowing both regroupings.'),T('First sum over v for fixed u. A telescoping reciprocal difference evaluates the inner sum.'),r'\sum_{v=1}^{\infty}\frac1{v(u+v)}=\frac{H_u}{u},\qquad B=S.',T('Next group by the total index n. The reciprocal numerator splits symmetrically, and the missing diagonal becomes a zeta term.'),r'\sum_{u=1}^{n-1}\frac1{u(n-u)}=\frac{2H_{n-1}}n,\qquad B=2\sum_{n=1}^{\infty}\frac{H_{n-1}}{n^2}=2S-2\zeta(3),\quad H_0=0.',r'S=2\zeta(3),\qquad\sum_{n='+str(m)+r'}^{\infty}\frac{H_n}{n^2}=2\zeta(3)-'+L(tail)+r'='+L(A)+r'.']
 checks=[eq('reciprocal split',1/(x*(z-x)),(1/x+1/(z-x))/z),eq('inner telescoping decomposition',1/(x*(x+z)),(1/x-1/(x+z))/z),eq('finite excluded prefix',sum(sum(R(1,h) for h in range(1,j+1))/j**2 for j in range(1,m)),tail)]
 return numeric(fid,i,Q,A,W,steps,checks,['H_n<=1+ln n makes S finite by integral comparison with (1+ln n)/n^2. Tonelli permits both nonnegative regroupings before finiteness is known. The first regrouping equals S, so B is finite and subtraction in the identity is legitimate.'],{'firstIndex':m})

@register('Pade-cancellation-order','Pade-exponential-integral-error','endpoint-vanishing-integration-by-parts','A high-order cancellation in an exponential rational approximation is exposed by an exact beta-integral remainder with vanishing endpoint derivatives.',('Taylor coefficients','integration by parts','beta integral'))
def pade(fid,i):
 m=i+3;Qpoly=sum((-1)**k*s.binomial(2*m-k,m)*x**k/s.factorial(k) for k in range(m+1));A=R((-1)**m,math.factorial(2*m+1))
 W=[(-A,'reverse the orientation of the endpoint remainder'),(A*s.factorial(m)**2,'omit the factorial normalization of the beta integral'),(A*s.binomial(2*m,m),'normalize the polynomial a second time'),(A/(2*m+2),'use the next Taylor order'),(A*(2*m+1),'use the previous Taylor factorial'),(-A/s.factorial(m),'combine a sign reversal with only one integration normalization')]
 Q=r'Q(x)=\sum_{k=0}^{'+str(m)+r'}\frac{(-1)^k}{k!}\binom{'+str(2*m)+r'-k}{'+str(m)+r'}x^k.\quad\lim_{x\to0}\frac{Q(x)e^x-Q(-x)}{x^{'+str(2*m+1)+r'}}=?'
 steps=[T('Choose a polynomial that vanishes to the required order at both integration endpoints.'),r'w(t)=t^{'+str(m)+r'}(1-t)^{'+str(m)+r'}.',T('Repeated integration by parts moves every derivative onto this polynomial. Its derivatives below order '+str(m)+' vanish at both endpoints, and its derivative above order '+str(2*m)+' vanishes identically. The remaining endpoint terms collect into the displayed Q polynomials.'),r'Q(x)e^x-Q(-x)=\frac{(-1)^{'+str(m)+r'}x^{'+str(2*m+1)+r'}}{('+str(m)+r'!)^2}\int_0^1t^{'+str(m)+r'}(1-t)^{'+str(m)+r'}e^{tx}\,\mathrm{d}t.',T('The integrand tends uniformly to the beta polynomial as x tends to zero. Evaluate that polynomial integral by repeated integration by parts.'),r'\int_0^1t^{'+str(m)+r'}(1-t)^{'+str(m)+r'}\,\mathrm{d}t=\frac{('+str(m)+r'!)^2}{'+str(2*m+1)+r'!}.',r'\lim_{x\to0}\frac{Q(x)e^x-Q(-x)}{x^{'+str(2*m+1)+r'}}=\frac{(-1)^{'+str(m)+r'}}{'+str(2*m+1)+r'!}='+L(A)+r'.']
 # Verify every lower coefficient rather than only the final limit.
 checks=[]
 for j in range(2*m+2):
  coeff=sum((-1)**k*s.binomial(2*m-k,m)/(s.factorial(k)*s.factorial(j-k)) for k in range(min(m,j)+1))-(s.binomial(2*m-j,m)/s.factorial(j) if j<=m else 0)
  checks.append(eq('Taylor coefficient order '+str(j),coeff,A if j==2*m+1 else 0))
 return numeric(fid,i,Q,A,W,steps,checks,['The integral identity is exact for real x, with its value at zero obtained continuously. The verifier independently expands the endpoint integration-by-parts polynomial and every Taylor coefficient through the first surviving order. Uniform convergence on the compact t interval justifies the final limit.'],{'order':m})

@register('factorial-asymptotic-remainder','divergent-series-optimal-scale-remainder','exact-geometric-remainder-and-Gamma-concentration','A divergent factorial expansion is truncated at a moving scale; an exact remainder integral and concentration, not a convergent Taylor argument, determine its size.',('Stirling asymptotics','integral moments','Chebyshev inequality'))
def factorial_remainder(fid,i):
 a=R(i+1,2);A=s.sqrt(2*s.pi)/(a+1)
 W=[(s.sqrt(2*s.pi)/a,'replace the moving denominator by its value at zero'),(s.sqrt(2*s.pi)/(a+2),'use an extra unit in the concentration location'),(s.sqrt(s.pi)/(a+1),'omit the factor two in Stirling normalization'),(2*s.sqrt(2*s.pi)/(a+1),'count both sides of a positive-axis saddle twice'),(s.sqrt(2*s.pi)/(a+1)**2,'square the resolvent denominator'),(s.sqrt(2*s.pi)*a/(a+1),'retain an extra denominator scale')]
 Q=r'F(x)=\int_0^\infty\frac{e^{-t}}{'+L(a)+r'+xt}\,\mathrm{d}t\quad(x>0),\qquad R_N=F(1/N)-\sum_{k=0}^{N-1}\frac{(-1)^k k!}{'+L(a)+r'^{\,k+1}N^k}.\quad\lim_{N\to\infty}\frac{(-1)^N'+L(a)+r'^{\,N}e^N}{\sqrt N}R_N=?'
 steps=[T('Use a finite geometric identity inside the integral. It is exact even though the infinite factorial expansion would diverge at every fixed positive x.'),r'\frac1{a+u}=\sum_{k=0}^{N-1}\frac{(-u)^k}{a^{k+1}}+\frac{(-u)^N}{a^N(a+u)},\qquad a='+L(a)+r'.',r'R_N=\frac{(-1)^N}{a^NN^N}\int_0^\infty\frac{t^Ne^{-t}}{a+t/N}\,\mathrm{d}t.',T('Normalize the nonnegative weight to a probability density. Integration by parts gives its first two moments.'),r'f_N(t)=\frac{t^Ne^{-t}}{N!}\quad(t>0),\qquad\mathbb E_N[t]=N+1,\quad\operatorname{Var}_N(t)=N+1.',T('Thus t divided by N tends to one in probability by Chebyshev. The reciprocal function is bounded by one over a and continuous, so its expectation tends to one over a plus one.'),r'\mathbb E_N\!\left[\frac1{a+t/N}\right]\longrightarrow\frac1{a+1}.',T('Stirling asymptotics supply the remaining normalization.'),r'\frac{(-1)^Na^Ne^N}{\sqrt N}R_N=\frac{N!e^N}{N^N\sqrt N}\mathbb E_N\!\left[\frac1{a+t/N}\right]\longrightarrow\frac{\sqrt{2\pi}}{a+1}='+L(A)+r'.']
 n=5;u=s.symbols('u');checks=[eq('finite geometric remainder at independent truncation',1/(a+u)-sum((-u)**k/a**(k+1) for k in range(n)),(-u)**n/(a**n*(a+u))),eq('Gamma-weight mean',s.factorial(n+1)/s.factorial(n),n+1),eq('Gamma-weight variance',s.factorial(n+2)/s.factorial(n)-(n+1)**2,n+1),truth('resolvent uniformly bounded',a>0)]
 return numeric(fid,i,Q,A,W,steps,checks,['Integrating each of finitely many polynomial terms uses integral t^k exp(-t)=k!, proved by integration by parts. Chebyshev gives E[(t/N-1)^2]=(N+2)/N^2 ->0. Boundedness and continuity give expectation convergence via splitting a small neighborhood and its complement. Stirling is an explicit analytic prerequisite; no numerical agreement is used as proof.'],{'a':str(a)})

@register('Hilbert-kernel-sharp-constant','sharp-Hilbert-series-inequality','Schur-weight-and-logarithmic-extremizers','A global sequence inequality needs both an operator upper bound and a finite-support family approaching that constant.',('Cauchy-Schwarz','integral comparison','sharp constants'))
def hilbert_sharp(fid,i):
 m=s.Integer(i+3);A=s.pi/m
 W=[(s.pi/(2*m),'discard one symmetric half of the kernel'),(2*s.pi/m,'count both symmetric halves twice'),(s.pi/(m+1),'treat the additive denominator shift as a multiplicative scale'),(s.pi/(m-1),'subtract the additive shift from the multiplicative scale'),(s.pi*s.pi/m,'square the norm constant when passing to the quadratic form'),(s.pi/(m*m),'apply the denominator scale twice')]
 Q=T('Find the least real constant C such that the inequality holds for every positive integer N and every real finite sequence.')+r'\quad\sum_{j,k=1}^{N}\frac{a_ja_k}{'+L(m)+r'(j+k+'+L(m)+r')}\le C\sum_{j=1}^{N}a_j^2.'
 steps=[T('First omit the positive additive shift to bound the absolute quadratic form. Use weights ')+r'w_j'+T(' equal to the reciprocal square root of j.'),r'\sum_{k=1}^{\infty}\frac{w_k}{j+k}\le\int_0^\infty\frac{t^{-1/2}}{j+t}\,\mathrm{d}t=\pi w_j,\qquad w_j=j^{-1/2}.',T('The integral comparison follows because its integrand decreases. Apply the weighted elementary inequality to each symmetric term, then sum.'),r'2|a_ja_k|\le a_j^2\frac{w_k}{w_j}+a_k^2\frac{w_j}{w_k}\quad\Longrightarrow\quad\sum_{j,k=1}^{N}\frac{|a_ja_k|}{j+k}\le\pi\sum_{j=1}^{N}a_j^2.',T('For sharpness take ')+r'a_j'+T(' equal to one over the square root of j through N. Their squared norm is asymptotic to the natural logarithm of N. For indices j between a large fixed K and N divided by K, integral comparison makes the normalized inner sum arbitrarily close to pi by first increasing K.'),r'\sqrt j\sum_{k=1}^{N}\frac{k^{-1/2}}{j+k+'+L(m)+r'}\ge\pi-\varepsilon\quad\left(K\le j\le N/K\right)',T('For any positive epsilon one can choose K large enough, then N large enough, for this bound to hold. The omitted logarithmic endpoint ranges contribute only a fixed amount to the squared norm.'),r'\lim_{N\to\infty}\frac{\sum_{j,k=1}^{N}(jk)^{-1/2}/(j+k+'+L(m)+r')}{\sum_{j=1}^{N}j^{-1}}=\pi,\qquad C=\frac\pi{'+L(m)+r'}.']
 u=s.symbols('u',positive=True);checks=[eq('Schur beta integral after square substitution',s.integrate(2/(1+u*u),(u,0,s.oo)),s.pi),truth('positive scale and shift',m>0)]
 return numeric(fid,i,Q,A,W,steps,checks,['For the lower bound compare the decreasing k-integrand with integral from 1 to N+1. After t=j u the normalized integral is integral from 1/j to (N+1)/j of u^-1/2/(1+u+m/j). For K<=j<=N/K it is at least integral from 1/K to K of u^-1/2/(1+u+m/K), which tends to pi as K tends to infinity. Summing 1/j over this middle range and dividing by H_N gives lower limit pi-epsilon. The Schur bound supplies the matching upper limit. No finite sequence attains equality, but least universal constant is proved.'],{'scaleAndShift':int(m)})

@register('Carleman-geometric-mean-constant','sharp-Carleman-geometric-mean-series','weighted-AMGM-telescope-and-Stirling-sharpness','A specially chosen telescoping weight proves the infinite geometric-mean inequality; a truncated harmonic sequence establishes the best constant.',('AM-GM','nonnegative summation','Stirling asymptotics'))
def carleman(fid,i):
 m=s.Integer(i+2);A=s.E/m
 W=[(1/m,'apply AM-GM without accounting for the repeated tail appearances'),(s.E/(m+1),'shift the external normalization by one'),(s.E/(m-1),'subtract one from the external normalization'),(s.E**2/m,'apply Stirling exponential normalization twice'),(s.E/(2*m),'halve the sharp harmonic asymptotic'),(2*s.E/m,'count the asymptotic weight twice')]
 Q=T('For nonnegative real sequences with finite sum, find the least constant C for which the inequality always holds.')+r'\quad\sum_{n=1}^{\infty}\left(\prod_{k=1}^{n}a_k\right)^{1/n}\le '+L(m)+r'C\sum_{n=1}^{\infty}a_n.'
 steps=[T('Introduce positive weights chosen so their finite product telescopes.'),r'c_k=\frac{(k+1)^k}{k^{k-1}},\qquad\prod_{k=1}^{n}c_k=(n+1)^n.',T('Apply AM-GM to the weighted variables, then divide by the geometric mean of the weights.'),r'\left(\prod_{k=1}^{n}a_k\right)^{1/n}\le\frac1{n(n+1)}\sum_{k=1}^{n}c_ka_k.',T('All summands are nonnegative, so reversing the sums is valid. The reciprocal coefficients telescope.'),r'\sum_{n=1}^{\infty}\left(\prod_{k=1}^{n}a_k\right)^{1/n}\le\sum_{k=1}^{\infty}c_ka_k\sum_{n=k}^{\infty}\frac1{n(n+1)}=\sum_{k=1}^{\infty}\left(1+\frac1k\right)^ka_k\le e\sum_{k=1}^{\infty}a_k.',T('To prove the constant cannot be smaller, take the reciprocal sequence through N and zero thereafter. Stirling makes its geometric means asymptotic to e divided by n.'),r'a_k=\begin{cases}1/k,&k\le N,\\0,&k>N,\end{cases}\qquad\frac{\sum_{n=1}^{N}(n!)^{-1/n}}{\sum_{n=1}^{N}1/n}\longrightarrow e.',r'C=\frac e{'+L(m)+r'}.']
 checks=[eq('telescoping weight product',s.prod(R((k+1)**k,k**(k-1)) for k in range(1,8)),8**7),eq('tail coefficient telescope',1/(x*(x+1)),1/x-1/(x+1))]
 return numeric(fid,i,Q,A,W,steps,checks,['AM-GM remains valid when some variables are zero. Tonelli handles nonnegative double sums. Stirling implies n*(n!)^(-1/n)->e; a finite-prefix plus tail comparison then gives the ratio of the two divergent partial sums tending to e. Each extremizing truncated sequence is admissible with finite support, so sharpness does not rely on a nonsummable test sequence being admissible.'],{'externalScale':int(m)})

@register('Dyson-alternating-cube','Dyson-constant-term-recurrence','Laurent-constant-term-and-Good-induction','A highly cancelling cubic binomial sum becomes a three-variable constant term with a proved dimension-reducing recurrence.',('Laurent polynomials','multinomial recurrence'))
def dyson(fid,i):
 m=i+2;A=s.factorial(3*m)/s.factorial(m)**3
 W=[(s.binomial(2*m,m)**3,'retain only the central term'),(s.factorial(3*m)/(s.factorial(m)*s.factorial(2*m)),'collapse two labeled variable groups'),(A/s.factorial(m),'divide once more by a block factorial'),(A*s.factorial(m),'omit one block factorial'),(A/2,'halve the alternating symmetric sum'),(2*A,'double both symmetric sides and the center')]
 Q=r'\sum_{k=-'+str(m)+r'}^{'+str(m)+r'}(-1)^k\binom{'+str(2*m)+r'}{'+str(m)+r'+k}^{\!3}=?'
 steps=[T('For a nonnegative integer m, let CT denote the coefficient of zero power in every variable of a Laurent polynomial. Pairing opposite ratios produces the binomial coefficients in the question.'),r'(1-u)^m(1-u^{-1})^m=\sum_{k=-m}^{m}(-1)^k\binom{2m}{m+k}u^k.',T('Use the three cyclic ratios of variables. A product term is constant exactly when its three selected exponents agree.'),r'\operatorname{CT}\prod_{1\le i\ne j\le3}(1-x_i/x_j)^m=\sum_{k=-m}^{m}(-1)^k\binom{2m}{m+k}^{3}.',T('More generally, let D(a,b,c) be this constant term when the exponent on each factor starting from variable i is the corresponding nonnegative integer a, b, or c. The following rational identity gives a recurrence when all three are positive.'),r'\sum_{i=1}^{3}\prod_{j\ne i}(1-x_i/x_j)^{-1}=1,\qquad D(a,b,c)=D(a-1,b,c)+D(a,b-1,c)+D(a,b,c-1).',T('When an exponent is zero, taking the constant term in that variable removes it, reducing to two variables and the ordinary binomial coefficient. Induction with these boundary values gives the multinomial expression.'),r'D(a,b,c)=\frac{(a+b+c)!}{a!b!c!},\qquad D('+str(m)+','+str(m)+','+str(m)+r')=\frac{'+str(3*m)+r'!}{('+str(m)+r'!)^3}='+L(A)+r'.']
 xs=s.symbols('x0:3');identity=sum(s.prod(1/(1-xs[j]/xs[k]) for k in range(3) if k!=j) for j in range(3));actual=sum(s.Integer(-1)**k*s.binomial(2*m,m+k)**3 for k in range(-m,m+1))
 checks=[eq('Good rational identity',identity,1),eq('independent finite alternating sum',actual,A)]
 return numeric(fid,i,Q,A,W,steps,checks,['For exponent vector (a_i), divide the product by product_(j!=i)(1-x_i/x_j) to decrease a_i by one; the rational identity implies the Laurent polynomial recurrence. At a_i=0 every remaining factor involving x_i contains only nonpositive powers of x_i, so its constant term forces all those choices to exponent zero, leaving the lower-dimensional product. In two variables the constant term is binomial(a+b,a) by Vandermonde. The multinomial factorial expression satisfies the same recurrence and all boundaries, completing induction.'],{'blockSize':m})

@register('Abel-logarithmic-sum','Abel-Cesaro-logarithmic-regularization','paired-Gamma-products-and-Cesaro-Abel','The ordinary series diverges, so finite paired products and a separate Cesaro-to-Abel argument are needed to evaluate the requested radial limit.',('Gamma recurrence','Stirling ratio','Abel summation'))
def abel_log(fid,i):
 a=[R(1,2),s.Integer(1),R(3,2),s.Integer(2),s.Integer(3),s.Integer(4),s.Integer(5),s.Integer(6)][i];C=s.log(s.gamma((a+1)/2)/s.gamma(a/2));A=C+s.log(2)/2
 W=[(C,'omit the half-logarithm arising between paired endpoints'),(-C+s.log(2)/2,'invert the paired Gamma ratio'),(C+s.log(2),'count the full odd endpoint logarithm rather than its Cesaro half'),(C-s.log(2)/2,'reverse the endpoint averaging correction'),(s.log(s.gamma((a+2)/2)/s.gamma((a+1)/2))+s.log(2)/2,'shift the series starting index by one'),(-A,'reverse the initial alternating sign')]
 Q=r'\lim_{r\uparrow1}\sum_{n=0}^{\infty}(-r)^n\ln\left(n+'+L(a)+r'\right)=?\qquad\Gamma(u)=\int_0^\infty t^{u-1}e^{-t}\,\mathrm{d}t\quad(u>0).'
 steps=[T('Let ')+r'S_M'+T(' denote the first M terms of the unweighted alternating logarithmic series. Pairing terms and using the Gamma recurrence gives a finite identity.'),r'S_{2N}=\ln\!\left(\frac{\Gamma(N+'+L(a/2)+r')\Gamma('+L((a+1)/2)+r')}{\Gamma('+L(a/2)+r')\Gamma(N+'+L((a+1)/2)+r')}\right).',r'C=\ln\!\left(\frac{\Gamma('+L((a+1)/2)+r')}{\Gamma('+L(a/2)+r')}\right),\qquad S_{2N}=-\frac12\ln N+C+o(1).',T('The adjacent odd partial sum includes one additional positive logarithm. Averaging the neighboring even and odd partial sums cancels their growing logarithms.'),r'S_{2N+1}=\frac12\ln N+C+\ln2+o(1),\qquad\frac{S_{2N}+S_{2N+1}}2\longrightarrow C+\frac12\ln2.',T('Therefore the averages of all partial sums tend to this same value. A second summation-by-parts identity turns those Cesaro averages into the requested Abel limit.'),r'\sum_{n=0}^{\infty}(-r)^n\ln(n+'+L(a)+r')=(1-r)^2\sum_{M=1}^{\infty}M\sigma_Mr^{M-1},\qquad\sigma_M=\frac1M\sum_{j=1}^{M}S_j.',T('The nonnegative weights on the right sum to one, and every fixed initial segment has total weight tending to zero. Since the Cesaro averages converge, their weighted average has the same limit.'),r'\lim_{r\uparrow1}\sum_{n=0}^{\infty}(-r)^n\ln(n+'+L(a)+r')=C+\frac12\ln2='+L(A)+r'.']
 N=4;finite=sum(s.log((2*j+a)/(2*j+a+1)) for j in range(N));product=s.prod((2*j+a)/(2*j+a+1) for j in range(N));gamma_ratio=s.gamma(N+a/2)*s.gamma((a+1)/2)/(s.gamma(a/2)*s.gamma(N+(a+1)/2));checks=[eq('finite paired Gamma product',s.expand_func(gamma_ratio),product),eq('Abel probability-weight normalization',s.diff(x/(1-x),x)*(1-x)**2,1)]
 return numeric(fid,i,Q,A,W,steps,checks,['The ordinary partial sums do not converge, so ordinary Abel theorem is not applied to them. Their consecutive pairs have a finite average limit, and any single unmatched partial sum is O(log M)/M in the Cesaro mean. Stirling gives Gamma(N+A)/Gamma(N+B)~N^(A-B). The twice-summed identity follows from S_M=sum_(n<M)c_n and M sigma_M=sum_(j<=M)S_j, with absolute convergence for r<1.'],{'shift':str(a)})

@register('maximum-entropy-sequence','countable-Gibbs-entropy-extremum','finite-coarsening-and-relative-entropy','A countably infinite optimization requires proving entropy is finite under the mean constraint, then identifying and attaining the geometric Gibbs bound.',('log-sum inequality','geometric series'))
def maximum_entropy(fid,i):
 m=s.Integer(i+2);r=(m-1)/m;A=m*s.log(m)-(m-1)*s.log(m-1)
 W=[(s.log(m),'assume the distribution is uniform on m points'),((m+1)*s.log(m+1)-m*s.log(m),'shift the allowed support to include zero'),(m*s.log(m)-(m-1)*s.log(m),'replace the shifted logarithm by the unshifted one'),(A/2,'insert a quadratic-energy normalization into entropy'),(2*A,'count both signs despite positive-integer support'),((m-1)*s.log(m)-(m-2)*s.log(m-1),'lose one unit of the mean in the logarithmic moment')]
 Q=T('Among real sequences satisfying these constraints, find the greatest entropy. The convention for zero terms is stated explicitly.')+r'\quad p_n\ge0,\quad\sum_{n=1}^{\infty}p_n=1,\quad\sum_{n=1}^{\infty}np_n='+L(m)+r',\quad H=-\sum_{n=1}^{\infty}p_n\ln p_n,\quad0\ln0=0.\qquad\max H=?'
 steps=[T('Choose the geometric comparison distribution with the required mean.'),r'r='+L(r)+r',\qquad q_n=(1-r)r^{n-1},\quad\sum_{n\ge1}q_n=1,\quad\sum_{n\ge1}nq_n=\frac1{1-r}='+L(m)+r'.',T('For a finite cutoff, combine all remaining probabilities into one tail category. The finite log-sum inequality bounds this coarse entropy by its cross-entropy against the same coarsening of q.'),r'P_N=\sum_{n>N}p_n,\quad Q_N=r^N,\qquad -\sum_{n=1}^{N}p_n\ln p_n-P_N\ln P_N\le-\sum_{n=1}^{N}p_n\ln q_n-P_N\ln Q_N.',T('The tail cross-entropy on the right is no larger than the full tail cross-entropy, because every tail index is at least N plus one. The full cross-entropy is finite by the mean constraint.'),r'-\sum_{n\ge1}p_n\ln q_n=-\ln(1-r)-('+L(m-1)+r')\ln r='+L(A)+r'.',T('Let the cutoff tend to infinity. Its tail probability tends to zero, so the coarse entropy tends to H; the finite bound proves H is finite and cannot exceed the displayed value. Taking p equal to q attains it.'),r'\max H='+L(A)+r'.']
 checks=[eq('comparison mean',1/(1-r),m),eq('geometric entropy algebra',s.expand_log(-s.log(1-r)-(m-1)*s.log(r),force=True),s.expand_log(A,force=True)),truth('geometric ratio in unit interval',0<r<1)]
 return numeric(fid,i,Q,A,W,steps,checks,['The finite log-sum inequality follows from concavity of ln, with zero probabilities handled by continuity. For n>N, -ln q_n=-ln(1-r)-(n-1)ln r>=-N ln r=-ln Q_N. Thus the coarse cross-entropy is bounded by the full one. The nonnegative entropy partial sums increase and -P_N ln P_N tends to zero. This argument establishes finiteness rather than assuming it to apply an infinite Gibbs inequality.'],{'mean':int(m)})

@register('restricted-digit-convergence','restricted-digit-Dirichlet-dimension','finite-state-counting-and-geometric-blocks','The convergence boundary comes from a constrained digit-language growth rate, requiring a recurrence count and sharp block bounds including the boundary.',('Fibonacci recurrence','comparison tests','base expansions'))
def restricted_digits(fid,i):
 b=s.Integer(i+3);phi=(1+s.sqrt(5))/2;A=s.log(phi)/s.log(b)
 W=[(s.log(2)/s.log(b),'allow adjacent ones in the digit count'),(s.log(phi)/(2*s.log(b)),'double the logarithmic scale per digit'),(2*s.log(phi)/s.log(b),'count both characteristic roots as growing modes'),(s.log(b)/s.log(phi),'invert the growth-to-size ratio'),(s.log(1+s.sqrt(2))/s.log(b),'use the recurrence for a two-step multiplicity-two language'),(s.log(phi)/s.log(b+1),'use the next base for the block sizes')]
 Q=T('Let S be the positive integers whose usual base expansion uses only digits zero and one and never has two adjacent ones. Leading zeros are excluded. Find the sharp constant c such that the displayed series converges exactly for p greater than c.')+r'\quad\textnormal{base }'+L(b)+r',\qquad\sum_{n\in S}\frac1{n^p},\quad p\in\mathbb R.'
 steps=[T('Let ')+r'A_L'+T(' be the number of allowed positive integers with exactly L digits. The first digit is one, and the following digit, when present, must be zero. Splitting the remaining strings by their final digit gives the Fibonacci recurrence.'),r'A_1=A_2=1,\qquad A_L=A_{L-1}+A_{L-2},\qquad A_L=\frac{\phi^L-\psi^L}{\sqrt5},\quad\phi=\frac{1+\sqrt5}2,\quad\psi=\frac{1-\sqrt5}2.',T('For a positive exponent p, every integer in the L-digit block lies between the corresponding consecutive powers of the base. Its whole block contribution is therefore bounded above and below by fixed multiples of the same geometric scale.'),r'A_L'+L(b)+r'^{-Lp}\le\sum_{\substack{n\in S\\n\textnormal{ has }L\textnormal{ digits}}}n^{-p}\le '+L(b)+r'^pA_L'+L(b)+r'^{-Lp}.',T('The growing characteristic root determines convergence. At equality the block contributions stay bounded away from zero, so the boundary diverges. For nonpositive p the summands themselves cannot tend to zero.'),r'\phi\,'+L(b)+r'^{-p}<1\quad\Longleftrightarrow\quad p>\frac{\ln\phi}{\ln '+L(b)+r'},\qquad c='+L(A)+r'.']
 counts=[]
 for Lg in range(1,9):counts.append(sum(bits[0]==1 and all(not(bits[j]==bits[j+1]==1) for j in range(Lg-1)) for bits in itertools.product([0,1],repeat=Lg)))
 checks=[truth('direct digit enumeration matches Fibonacci counts',counts==[int(s.fibonacci(j)) for j in range(1,9)]),eq('growing root characteristic equation',phi*phi,phi+1),truth('base exceeds allowed largest digit',b>=3)]
 return numeric(fid,i,Q,A,W,steps,checks,['The finite-state count includes leading-one restriction, giving Fibonacci F_L, not F_(L+2). The smaller characteristic root has magnitude below one, so A_L/phi^L tends to 1/sqrt5. Two-sided block comparison then proves both convergence and divergence, including the sharp endpoint.'],{'base':int(b)})

@register('binomial-convolution-Riccati','exponential-convolution-generating-Riccati','EGF-product-and-initial-value-branch','Binomial convolution becomes a nonlinear differential equation only in the exponential generating function; its analytic solution and first pole establish the valid evaluation.',('exponential generating functions','separable differential equation'))
def riccati_series(fid,i):
 m=s.Integer(i+4);t=s.pi/m;A=s.tan(s.pi/4+t/2)
 W=[(s.tan(s.pi/4+t),'omit the half in the differential equation'),(s.tan(t/2),'drop the initial value of the generating function'),(1/s.cos(t),'omit the odd tangent part'),(s.tan(s.pi/4-t/2),'reverse the derivative sign'),(1/s.cos(t)+2*s.tan(t),'double the odd part of the solution'),(1/s.cos(t)+s.tan(t)/2,'halve the odd part after solving the equation')]
 Q=r'a_0=1,\quad a_1=1,\qquad a_{n+1}=\frac12\sum_{k=0}^{n}\binom nk a_ka_{n-k}\quad(n\ge1).\quad\sum_{n=0}^{\infty}\frac{a_n}{n!}\left(\frac\pi{'+L(m)+r'}\right)^n=?'
 steps=[T('Define the exponential generating function. Its product coefficients contain exactly the binomial convolution in the recurrence.'),r'F(z)=\sum_{n=0}^{\infty}\frac{a_nz^n}{n!},\qquad F\prime(z)=\frac{F(z)^2+1}{2},\quad F(0)=1.',T('The constant correction accounts for the separate initial relation at index zero. Solve the separable initial-value equation on its branch through one.'),r'\arctan F(z)=\frac z2+\frac\pi4,\qquad F(z)=\tan\!\left(\frac\pi4+\frac z2\right).',T('This analytic function has nearest pole at pi over two, so its Taylor series converges at the displayed argument. Its coefficients satisfy the original recurrence and initial values, proving they are the specified coefficients without assuming convergence of an unknown formal series.'),r'F\left(\frac\pi{'+L(m)+r'}\right)=\tan\!\left(\frac\pi4+\frac\pi{'+L(2*m)+r'}\right)='+L(A)+r'.']
 F=s.tan(s.pi/4+x/2);checks=[eq('Riccati equation',s.trigsimp(s.diff(F,x)-(F*F+1)/2),0),eq('initial value',F.subs(x,0),1),truth('evaluation before first pole',0<t<s.pi/2)]
 return numeric(fid,i,Q,A,W,steps,checks,['Formal exponential series multiplication gives the convolution coefficient. The explicit analytic solution has nearest poles at pi/2 and -3pi/2; all other poles are farther away, so radius is pi/2. Recurrence uniqueness identifies every coefficient. The antiderivative identity is used locally with arctan F(0)=pi/4; no unsupported global branch continuation is asserted.'],{'angleDenominator':int(m)})

